-- 'ok' | 'fail' | 'locked'. A failure is recorded here, so callers must return (not raise) on a non-ok result.
create or replace function public.mood_pw_check(p_user text, p_pw text) returns text
 language plpgsql security definer set search_path to 'public', 'pg_temp'
as $$
declare
  v_ip text := public.mood_client_ip();
  v_user text := left(coalesce(p_user, ''), 100);
  v_headers json := nullif(current_setting('request.headers', true), '')::json;
  v_stored text;
begin
  -- Refuse requests whose transaction PostgREST would not commit (GET/HEAD run read-only; a single-object
  -- Accept rolls back on 0 rows), so a failed guess always leaves a failure row.
  if current_setting('transaction_read_only') = 'on'
     or coalesce(v_headers ->> 'accept', '') ilike '%vnd.pgrst%'
     or coalesce(v_headers ->> 'prefer', '') ~* '(tx=|max-affected|handling)' then
    raise exception 'Unsupported request';
  end if;
  -- Serialize attempts per username and per IP so parallel guesses cannot all pass the threshold checks.
  perform pg_advisory_xact_lock(hashtextextended('mood_auth:' || v_user, 0));
  perform pg_advisory_xact_lock(hashtextextended('mood_auth_ip:' || v_ip, 0));
  if (select count(*) from public.mood_auth_failures
       where username = v_user and at > now() - interval '15 minutes') >= 10
     or (v_ip <> '' and (select count(*) from public.mood_auth_failures
       where ip = v_ip and at > now() - interval '15 minutes') >= 30) then
    return 'locked';
  end if;
  select u.password into v_stored from public.users u where u.username = p_user;
  -- The web client always sends a lowercase SHA-256 hex digest; anything else (e.g. >72 bytes for bcrypt) is a failure.
  if nullif(btrim(p_user), '') is not null and p_pw ~ '^[0-9a-f]{64}$' and v_stored is not null
     and v_stored like '$2%' and extensions.crypt(p_pw, v_stored) = v_stored then
    return 'ok';
  end if;
  insert into public.mood_auth_failures (username, ip) values (v_user, v_ip);
  delete from public.mood_auth_failures where at < now() - interval '1 day';
  return 'fail';
end $$;
