CREATE OR REPLACE FUNCTION public.get_records_secure(p_user text, p_pw text, p_target text, p_start date, p_end date)
 RETURNS TABLE(record_date date, category text, value text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
    v_stored_pw TEXT;
BEGIN
    SELECT u.password
    INTO v_stored_pw
    FROM public.users AS u
    WHERE u.username = p_user;

    IF NULLIF(btrim(p_user), '') IS NULL OR NULLIF(btrim(p_pw), '') IS NULL OR public.mood_pw_check(p_user, p_pw) <> 'ok' THEN
        PERFORM set_config('response.status', '401', true);
        RETURN;
    END IF;

    RETURN QUERY
    SELECT r.record_date, r.category, r.value
    FROM public.records AS r
    WHERE r.username = p_user
      AND r.record_date BETWEEN p_start AND p_end
    ORDER BY r.record_date, r.category;
END;
$function$;

CREATE OR REPLACE FUNCTION public.get_inventory_secure(p_user text, p_pw text)
 RETURNS TABLE(id bigint, icon text, source text, is_new boolean, sender text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_stored_pw TEXT;
BEGIN
    SELECT password INTO v_stored_pw FROM users WHERE username = p_user;
    IF NULLIF(btrim(p_user), '') IS NULL OR NULLIF(btrim(p_pw), '') IS NULL OR public.mood_pw_check(p_user, p_pw) <> 'ok' THEN PERFORM set_config('response.status', '401', true); RETURN; END IF;
    RETURN QUERY SELECT i.id, i.icon, i.source, i.is_new, i.sender_username FROM inventory i WHERE i.username = p_user ORDER BY i.id DESC;
END;
$function$;

CREATE OR REPLACE FUNCTION public.send_gift_secure(p_user text, p_pw text, p_inv_id bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare 
    v_stored_pw text;
    v_target text;
    v_icon text;
    v_origin_source text;
    v_new_source text;
    v_tier_suffix text;
    v_dummy bigint;
    v_sent_count int;
    v_milestone_icon text;
    v_special_sent_icons text[] := array[
      '🪽','🕊️','🦢','🦚','🦜','🦩','🦥','🦔','🦦','🦊','🦄','🐉','🐲','🦌','🦘','🦙','🦬','🦧','🦫','🦎','🦂','🐈‍⬛','🐇','🐿️','🦨','🦭','🪻','🌸','💮','🏵️','🪷','🌺','🌼','🌻','🌷','🪴','🪹','🪺','🪵','🌵','🎋','🎍','🌿','🍀','🍁','🍂','🍄','🪨','🧿','💎','🔮','📿','💠','🪬','🪙','🪅','🪄','🪡','🪞','🪩','💫','✨','🌙','⭐','🌈','🌌','☄️','🧚','🧚‍♀️','🧚‍♂️','🧜','🧜‍♀️','🧝','🧝‍♀️','🧞','🧞‍♀️','🧞‍♂️','🧟','🧌','🐚','🪸','🌊','🌫️','🌠','🐯','🐺','🦁','🐵','🙈','🙉','🙊','🐼','🦝','🦡','🐹','🐭','🐰','🐻','🐻‍❄️','🐨','🐱','🐶','🐸','🐧','🐢','🐍','🕷️','🦋','🐝','🐞','🪲','🪳','🪰','🪱','🧸','🎠','🎡','🎪','🎁','🎀','🎈','🎇','🎆','🌟','💍','💜','💖','💗','💘','💝','🗡️','⚔️','🛡️','🏺','🗿','🧭','⏳','⌛','🕰️','⚱️','🌹','🥀','🌱','🌌','🌋','🌧️','🌤️'
    ];
begin
    select password into v_stored_pw
    from users
    where username = p_user;

    IF NULLIF(btrim(p_user), '') IS NULL OR NULLIF(btrim(p_pw), '') IS NULL OR public.mood_pw_check(p_user, p_pw) <> 'ok' then
        PERFORM set_config('response.status', '401', true);
        return jsonb_build_object('message', 'Auth failed', 'code', 'P0001');
    end if;

    delete from inventory
    where id = p_inv_id
      and username = p_user
    returning icon, source into v_icon, v_origin_source;

    if v_icon is null then
        raise exception 'Item not found or already sent';
    end if;
    
    select username into v_target
    from users u
    where u.username != p_user
      and exists (
        select 1
        from records r
        where r.username = u.username
          and r.record_date >= (current_date - interval '60 days')
      )
    order by random()
    limit 1;
    
    if v_target is null then
        v_target := 'admin';
    end if;

    if v_target = p_user then
        return jsonb_build_object('status', 'no_users');
    end if;
    
    if v_origin_source like '%milestone%' or v_origin_source like '%special%' then
        v_tier_suffix := substring(v_origin_source from '[0-9]+$');
        if v_tier_suffix is not null then
            v_new_source := 'gift_milestone_' || v_tier_suffix;
        else
            v_new_source := 'gift_milestone';
        end if;
    else
        v_new_source := 'gift';
    end if;

    insert into inventory (username, icon, source, is_new, sender_username)
    values (v_target, v_icon, v_new_source, true, p_user);

    select count(*) into v_sent_count
    from inventory
    where sender_username = p_user
      and source like 'gift%';
    
    if v_sent_count > 0 and (v_sent_count = 10 or (v_sent_count >= 50 and v_sent_count % 50 = 0)) then
        v_milestone_icon := v_special_sent_icons[floor(random() * array_length(v_special_sent_icons, 1) + 1)];
        insert into inventory (username, icon, source, is_new)
        select p_user, v_milestone_icon, 'milestone_sent_' || v_sent_count, true
        where not exists (
            select 1
            from inventory
            where username = p_user
              and source = 'milestone_sent_' || v_sent_count
        )
        returning id into v_dummy;

        if v_dummy is not null then
            return jsonb_build_object('status', 'milestone', 'count', v_sent_count, 'icon', v_milestone_icon);
        end if;
    end if;
    
    return jsonb_build_object('status', 'success');
end;
$function$;

CREATE OR REPLACE FUNCTION public.send_reply_gift_secure(p_user text, p_pw text, p_my_item_id bigint, p_received_item_id bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare 
    v_stored_pw text;
    v_my_icon text;
    v_origin_source text;
    v_new_source text;
    v_tier_suffix text;
    v_target_user text;
    v_received_source text;
    v_recv_count int;
    v_milestone_icon text;
    v_special_reply_icons text[] := array[
      '🪽','🕊️','🦢','🦚','🦜','🦩','🦥','🦔','🦦','🦊','🦄','🐉','🐲','🦌','🦘','🦙','🦬','🦧','🦫','🦎','🦂','🐈‍⬛','🐇','🐿️','🦨','🦭','🪻','🌸','💮','🏵️','🪷','🌺','🌼','🌻','🌷','🪴','🪹','🪺','🪵','🌵','🎋','🎍','🌿','🍀','🍁','🍂','🍄','🪨','🧿','💎','🔮','📿','💠','🪬','🪙','🪅','🪄','🪡','🪞','🪩','💫','✨','🌙','⭐','🌈','🌌','☄️','🧚','🧚‍♀️','🧚‍♂️','🧜','🧜‍♀️','🧝','🧝‍♀️','🧞','🧞‍♀️','🧞‍♂️','🧟','🧌','🐚','🪸','🌊','🌫️','🌠','🐯','🐺','🦁','🐵','🙈','🙉','🙊','🐼','🦝','🦡','🐹','🐭','🐰','🐻','🐻‍❄️','🐨','🐱','🐶','🐸','🐧','🐢','🐍','🕷️','🦋','🐝','🐞','🪲','🪳','🪰','🪱','🧸','🎠','🎡','🎪','🎁','🎀','🎈','🎇','🎆','🌟','💍','💜','💖','💗','💘','💝','🗡️','⚔️','🛡️','🏺','🗿','🧭','⏳','⌛','🕰️','⚱️','🌹','🥀','🌱','🌌','🌋','🌧️','🌤️'
    ];
begin
    select password into v_stored_pw
    from users
    where username = p_user;

    IF NULLIF(btrim(p_user), '') IS NULL OR NULLIF(btrim(p_pw), '') IS NULL OR public.mood_pw_check(p_user, p_pw) <> 'ok' then
        PERFORM set_config('response.status', '401', true);
        return jsonb_build_object('message', 'Auth failed', 'code', 'P0001');
    end if;

    update inventory
    set source = source || '_replied'
    where id = p_received_item_id
      and username = p_user
      and source not like '%_replied'
      and source not like 'gift_reply%'
    returning sender_username, source into v_target_user, v_received_source;

    if v_target_user is null then
        return jsonb_build_object('status', 'cannot_reply_again_or_not_found');
    end if;

    delete from inventory
    where id = p_my_item_id
      and username = p_user
    returning icon, source into v_my_icon, v_origin_source;

    if v_my_icon is null then
        raise exception 'My item not found or already used';
    end if;

    if v_origin_source like '%milestone%' or v_origin_source like '%special%' then
        v_tier_suffix := substring(v_origin_source from '[0-9]+$');
        if v_tier_suffix is not null then
            v_new_source := 'gift_reply_milestone_' || v_tier_suffix;
        else
            v_new_source := 'gift_reply_milestone';
        end if;
    else
        v_new_source := 'gift_reply';
    end if;

    insert into inventory (username, icon, source, is_new, sender_username)
    values (v_target_user, v_my_icon, v_new_source, true, p_user);

    select count(*) into v_recv_count
    from inventory
    where username = v_target_user
      and source like 'gift_reply%';
    
    if v_recv_count > 0 and (v_recv_count = 10 or (v_recv_count >= 50 and v_recv_count % 50 = 0)) then
        v_milestone_icon := v_special_reply_icons[floor(random() * array_length(v_special_reply_icons, 1) + 1)];
        insert into inventory (username, icon, source, is_new)
        select v_target_user, v_milestone_icon, 'milestone_recv_' || v_recv_count, true
        where not exists (
            select 1
            from inventory
            where username = v_target_user
              and source = 'milestone_recv_' || v_recv_count
        );
    end if;

    return jsonb_build_object('status', 'success');
end;
$function$;

CREATE OR REPLACE FUNCTION public.upsert_record_secure(p_user text, p_pw text, p_date date, p_cat text, p_val text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
    v_user_row users%ROWTYPE; v_diff INT; v_points NUMERIC := 0; v_streak_bonus NUMERIC := 0;
    v_is_update BOOLEAN := FALSE; v_is_insert BOOLEAN := FALSE; 
    v_current_points NUMERIC; v_reward_icon TEXT := NULL; v_source_key TEXT;
    v_group1 TEXT[] := ARRAY['m_p4', 'm_p3', 'm_p2', 'm_p1', 'm_0', 'm_m1', 'm_m2', 'm_m3', 'm_m4', 'mixed', 's_anx', 's_ang', 's_mot', 's_act', 's_tsp', 's_tct', 'sleep', 'weight'];
    v_group2 TEXT[] := ARRAY['period', 'alcoh', 'binge', 'pain', 'cry', 'panic', 'hyper', 'meds', 'exer', 'event'];
    v_has_any_today BOOLEAN; v_has_group2_today BOOLEAN;
    v_icons TEXT[] := ARRAY['🐶','🐱','🐭','🐹','🐰','🦊','🐻','🐼','🐨','🐯','🦁','🐮','🐷','🐸','🐵','🐔','🐧','🐦','🐤','🦆','🦅','🦉','🦇','🐺','🐗','🐴','🦄','🐝','🐛','🦋','🐌','🐞','🐜','🐢','🐍','🦎','🐙','🦑','🦞','🦀','🐡','🐠','🐟','🐬','🐳','🐋','🦈','🐊','🐅','🐆','🦓','🦍','🐘','🦛','🦏','🐪','🐫','🦒','🦘','🦬','🐃','🐂','🐄','🐎','🐖','🐏','🐑','🐐','🦌','🐕','🐩','🐈','🐓','🦃','🦚','🦜','🦢','🦩','🕊','🐇','🦝','🦨','🦡','🦦','🦫','🦥','🐁','🐀','🐿','🦔','🐾','🌵','🎄','🌲','🌳','🌴','🌱','🌿','☘️','🍀','🎍','🎋','🍃','🍂','🍁','🍄','🌾','💐','🌷','🌹','🥀','🌺','🌸','🌼','🌻','🌞','🌝','⭐️','🌟','✨','⚡️','🔥','🌈','🌊','❄️','⛄️','🌬','🍏','🍎','🍐','🍊','🍋','🍌','🍉','🍇','🍓','🫐','🍈','🍒','🍑','🥭','🍍','🥥','🥝','🍅','🥑','🍆','🥕','🌽','🌶','🥒','🥦','🍄','🥜','🌰','🍞','🥐','🥖','🥯','🥞','🧇','🧀','🍖','🍗','🍔','🍟','🍕','🌭','🥪','🌮','🌯','🥙','🥚','🍳','🥘','🍲','🥣','🥗','🍿','🍱','🍘','🍙','🍚','🍛','🍜','🍝','🍠','🍢','🍣','🍤','🍥','🥮','🍡','🥟','🥠','🍦','🍧','🍨','🍩','🍪','🎂','🍰','🧁','🥧','🍫','🍬','🍭','🍮','🍯','🍼','☕️','🫖','🍵','🍹','🍺','🥂','🍷','🎈','🎆','🎇','🧨','🎉','🎊','🎋','🎍','🎎','🎏','🎐','🎑','🎀','🎁','🎗','🎟','🎫','🎖','🏆','🏅','🥇','🥈','🥉','⚽️','🏀','🏈','⚾️','🥎','🎾','🏐','🏉','🥏','🎳','🏏','🏑','🏒','🥍','🏓','🏸','🥊','🥋','🥅','⛳️','⛸','🎣','🤿','🎽','🎿','🛷','🥌','🎯','🪀','🪁','🎱','🔮','🧿','🎮','🕹','🎰','🎲','🧩','🧸','🪅','🪆','♠️','♥️','♦️','♣️','♟','🃏','🀄️','🎴','🎭','🖼','🎨','🧵','🧶','🎼','🎤','🎧','🎷','🎸','🎹','🎺','🎻','🪕','🥁','😀','😃','😄','😁','😆','😅','😂','🤣','🥲','☺️','😊','😇','🙂','🙃','😉','😌','😍','🥰','😘','😗','😙','😚','😋','😛','😝','😜','🤪','🤨','🧐','🤓','😎','🥸','🤩','🥳','😏','❤️','🧡','💛','💚','💙','💜','🖤','🤍','🤎','💔','❤️‍🔥','❤️‍🩹','❣️','💕','💞','💓','💗','💖','💘','💝'];
BEGIN
    SELECT * INTO v_user_row FROM users WHERE username = p_user;
    IF NULLIF(btrim(p_user), '') IS NULL OR NULLIF(btrim(p_pw), '') IS NULL OR public.mood_pw_check(p_user, p_pw) <> 'ok' THEN PERFORM set_config('response.status', '401', true); RETURN jsonb_build_object('message', 'Auth failed', 'code', 'P0001'); END IF;

    IF p_val IS NULL OR p_val = '' THEN
        DELETE FROM records WHERE username = p_user AND record_date = p_date AND category = p_cat;
        SELECT points INTO v_current_points FROM users WHERE username = p_user;
        RETURN jsonb_build_object('status', 'deleted', 'points', v_current_points);
    END IF;

    SELECT EXISTS(SELECT 1 FROM records WHERE username = p_user AND record_date = p_date) INTO v_has_any_today;
    SELECT EXISTS(SELECT 1 FROM records WHERE username = p_user AND record_date = p_date AND category = ANY(v_group2)) INTO v_has_group2_today;
    
    SELECT EXISTS(SELECT 1 FROM records WHERE username = p_user AND record_date = p_date AND category = p_cat) INTO v_is_update;
    v_is_insert := NOT v_is_update;

    INSERT INTO records (username, record_date, category, value, created_at, updated_at)
    VALUES (p_user, p_date, p_cat, p_val, NOW(), NOW())
    ON CONFLICT (username, record_date, category)
    DO UPDATE SET value = EXCLUDED.value, updated_at = NOW();

    IF v_is_insert AND p_date >= v_user_row.created_at::DATE THEN
        IF p_cat = ANY(v_group1) THEN v_points := 1;
        ELSIF p_cat = ANY(v_group2) THEN IF v_has_group2_today THEN v_points := 0; ELSE v_points := 2; END IF; END IF;
        
        v_diff := (CURRENT_DATE - p_date);
        IF v_diff <= 3 THEN v_points := v_points * 1; 
        ELSIF v_diff <= 7 THEN v_points := v_points * 0.5; 
        ELSE v_points := v_points * 0.1; END IF;
        
        IF v_diff < 0 THEN v_points := 0; END IF;

        IF NOT v_has_any_today AND v_points > 0 THEN
            PERFORM 1 FROM records WHERE username = p_user AND record_date = p_date - 1;
            IF FOUND THEN v_streak_bonus := 1;
                PERFORM 1 FROM records WHERE username = p_user AND record_date = p_date - 2;
                IF FOUND THEN v_streak_bonus := 2;
                    PERFORM 1 FROM records WHERE username = p_user AND record_date = p_date - 3;
                    IF FOUND THEN v_streak_bonus := 3; END IF;
                END IF;
            END IF;
        END IF;
        v_points := v_points + v_streak_bonus;
        IF v_points > 0 THEN 
            UPDATE users SET points = points + v_points WHERE username = p_user; 
        END IF;
    END IF;

    IF p_cat IN ('score_ls', 'score_mssi') THEN
        IF p_date >= DATE_TRUNC('month', CURRENT_DATE - INTERVAL '1 month')::DATE THEN
            v_source_key := 'monthly_reward_' || p_cat || '_' || TO_CHAR(p_date, 'YYYYMM');
            v_reward_icon := v_icons[floor(random() * array_length(v_icons, 1) + 1)];
            
            INSERT INTO inventory (username, icon, source, is_new)
            SELECT p_user, v_reward_icon, v_source_key, TRUE
            WHERE NOT EXISTS (
                SELECT 1 FROM inventory WHERE username = p_user AND source = v_source_key
            );
            
            PERFORM 1 FROM inventory WHERE username = p_user AND source = v_source_key AND icon = v_reward_icon;
            IF NOT FOUND THEN v_reward_icon := NULL; END IF;
        END IF;
    END IF;

    SELECT points INTO v_current_points FROM users WHERE username = p_user;
    RETURN jsonb_build_object('status', 'success', 'points', v_current_points, 'earned', v_points, 'bonus', v_streak_bonus, 'reward_icon', v_reward_icon);
END;
$function$;

CREATE OR REPLACE FUNCTION public.unlock_reward_secure(p_user text, p_pw text, p_icon text)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE 
    v_pts NUMERIC; v_stored_pw TEXT;
BEGIN
    SELECT password INTO v_stored_pw FROM users WHERE username = p_user;
    IF NULLIF(btrim(p_user), '') IS NULL OR NULLIF(btrim(p_pw), '') IS NULL OR public.mood_pw_check(p_user, p_pw) <> 'ok' THEN PERFORM set_config('response.status', '401', true); RETURN 'Auth failed'; END IF;

    UPDATE users SET points = points - 70 WHERE username = p_user AND points >= 70 RETURNING points INTO v_pts;
    IF NOT FOUND THEN RETURN 'keep_going'; END IF;

    INSERT INTO inventory (username, icon, source) VALUES (p_user, p_icon, 'earn');
    RETURN 'success';
END;
$function$;

CREATE OR REPLACE FUNCTION public.check_gift_reception_secure(p_user text, p_pw text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_count INT; v_stored_pw TEXT; v_mile_rec RECORD;
BEGIN
    SELECT password INTO v_stored_pw FROM users WHERE username = p_user;
    IF NULLIF(btrim(p_user), '') IS NULL OR NULLIF(btrim(p_pw), '') IS NULL OR public.mood_pw_check(p_user, p_pw) <> 'ok' THEN RETURN jsonb_build_object('status', 'fail'); END IF;
    
    -- 마일스톤 특별 선물 우선 확인
    SELECT * INTO v_mile_rec FROM inventory WHERE username = p_user AND source LIKE 'milestone_%' AND is_new = TRUE ORDER BY id DESC LIMIT 1;
    IF FOUND THEN
        UPDATE inventory SET is_new = FALSE WHERE id = v_mile_rec.id;
        RETURN jsonb_build_object(
            'status', 'milestone', 
            'icon', v_mile_rec.icon, 
            'msg', CASE WHEN v_mile_rec.source LIKE 'milestone_sent_%' THEN '따뜻한 마음을 가진 당신에게 특별한 선물을 드려요!' ELSE '서로 격려하는 당신에게 특별한 선물을 드려요!' END
        );
    END IF;

    -- 일반 선물 확인
    SELECT COUNT(*) INTO v_count FROM inventory WHERE username = p_user AND source IN ('gift', 'gift_reply') AND is_new = TRUE;
    IF v_count > 0 THEN
        UPDATE inventory SET is_new = FALSE WHERE username = p_user AND source IN ('gift', 'gift_reply');
        RETURN jsonb_build_object('status', 'normal', 'count', v_count);
    END IF;

    RETURN jsonb_build_object('status', 'none');
END;
$function$;

CREATE OR REPLACE FUNCTION public.check_special_event_secure(p_user text, p_pw text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
    v_stored_pw TEXT; 
    v_today DATE := (NOW() AT TIME ZONE 'Asia/Seoul')::DATE; 
    v_year TEXT := TO_CHAR(v_today, 'YYYY'); 
    v_mmdd TEXT := TO_CHAR(v_today, 'MMDD');
    v_msg TEXT := ''; v_icon TEXT := ''; v_source_key TEXT := '';
    v_digits TEXT; v_birth_mmdd TEXT; v_chuseok DATE; v_dummy BIGINT;
BEGIN
    SELECT password INTO v_stored_pw FROM users WHERE username = p_user;
    IF NULLIF(btrim(p_user), '') IS NULL OR NULLIF(btrim(p_pw), '') IS NULL OR public.mood_pw_check(p_user, p_pw) <> 'ok' THEN RETURN jsonb_build_object('status', 'fail'); END IF;

    IF v_mmdd = '0101' THEN v_source_key := 'event_newyear_' || v_year; v_icon := '🌅'; v_msg := '☀️ 새해 복 많이 받으세요!';
    ELSIF v_mmdd = '1225' THEN v_source_key := 'event_xmas_' || v_year; v_icon := '🎄'; v_msg := '🎅 메리 크리스마스!';
    ELSE
        CASE v_year WHEN '2025' THEN v_chuseok := '2025-10-06'; WHEN '2026' THEN v_chuseok := '2026-09-25'; ELSE v_chuseok := NULL; END CASE;
        IF v_today = v_chuseok THEN v_source_key := 'event_chuseok_' || v_year; v_icon := '🌕'; v_msg := '🍂 풍성한 한가위 되세요!'; END IF;
    END IF;
    
    IF v_source_key = '' THEN
        v_digits := REGEXP_REPLACE(p_user, '[^0-9]', '', 'g');
        IF LENGTH(v_digits) >= 4 THEN
            v_birth_mmdd := RIGHT(v_digits, 4);
            IF v_birth_mmdd = v_mmdd AND SUBSTRING(v_birth_mmdd, 1, 2)::INT BETWEEN 1 AND 12 AND SUBSTRING(v_birth_mmdd, 3, 2)::INT BETWEEN 1 AND 31 THEN
                v_source_key := 'event_birth_' || v_year; v_icon := '🎂'; v_msg := '🎉 생일을 축하합니다!';
            END IF;
        END IF;
    END IF;

    IF v_source_key != '' THEN
        INSERT INTO inventory (username, icon, source, is_new)
        SELECT p_user, v_icon, v_source_key, TRUE
        WHERE NOT EXISTS (SELECT 1 FROM inventory WHERE username = p_user AND source = v_source_key)
        RETURNING id INTO v_dummy;

        IF v_dummy IS NOT NULL THEN RETURN jsonb_build_object('status', 'success', 'icon', v_icon, 'msg', v_msg); END IF;
    END IF;
    RETURN jsonb_build_object('status', 'none');
END;
$function$;

CREATE OR REPLACE FUNCTION public.change_password_secure(p_user text, p_old_pw text, p_new_pw text)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_stored_pw TEXT;
BEGIN
    SELECT password INTO v_stored_pw FROM users WHERE username = p_user;
    IF NULLIF(btrim(p_user), '') IS NULL OR NULLIF(btrim(p_old_pw), '') IS NULL OR public.mood_pw_check(p_user, p_old_pw) <> 'ok' OR COALESCE(p_new_pw, '') !~ '^[0-9a-f]{64}$' THEN RETURN 'fail'; END IF;
    UPDATE users SET password = extensions.crypt(p_new_pw, extensions.gen_salt('bf', 8)) WHERE username = p_user;
    RETURN 'success';
END;
$function$;

CREATE OR REPLACE FUNCTION public.register_user_secure(p_id text, p_pw text, p_hosp text)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
    IF COALESCE(p_pw, '') !~ '^[0-9a-f]{64}$' THEN
        RETURN 'invalid_password';
    END IF;

    IF lower(trim(COALESCE(p_id, ''))) IN ('admin', 'administrator') THEN
        RETURN 'duplicate_id';
    END IF;

    PERFORM 1 FROM public.users WHERE username = p_id;
    IF FOUND THEN
        RETURN 'duplicate_id';
    END IF;

    IF p_hosp IS NOT NULL AND trim(p_hosp) != '' THEN
        PERFORM 1 FROM public.users WHERE hospital_id = p_hosp;
        IF FOUND THEN
            RETURN 'duplicate_hosp';
        END IF;
    END IF;

    INSERT INTO public.users (username, password, hospital_id, points, created_at)
    VALUES (p_id, extensions.crypt(p_pw, extensions.gen_salt('bf', 8)), p_hosp, 0, now());

    RETURN 'success';
EXCEPTION
    WHEN unique_violation THEN
        RETURN 'duplicate';
END;
$function$;

CREATE OR REPLACE FUNCTION public.create_mood_persistent_login(p_user text, p_pw text, p_role text, p_token_hash text, p_user_agent text DEFAULT ''::text, p_days integer DEFAULT 30)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_days INTEGER := LEAST(GREATEST(COALESCE(p_days, 30), 1), 30);
  v_role TEXT := 'patient';
  v_expires_at TIMESTAMPTZ := now() + (v_days || ' days')::interval;
BEGIN
  IF NULLIF(TRIM(p_user), '') IS NULL OR NULLIF(TRIM(p_pw), '') IS NULL THEN
    RAISE EXCEPTION 'Auth failed';
  END IF;
  IF NULLIF(TRIM(p_token_hash), '') IS NULL OR char_length(p_token_hash) < 40 THEN
    RAISE EXCEPTION 'Invalid device token';
  END IF;

  IF public.mood_pw_check(p_user, p_pw) <> 'ok' THEN
    PERFORM set_config('response.status', '401', true);
    RETURN jsonb_build_object('message', 'Auth failed', 'code', 'P0001');
  END IF;

  BEGIN
    PERFORM *
    FROM public.resolve_patient_id_secure(p_user, p_pw, '')
    LIMIT 1;
    v_role := 'doctor';
  EXCEPTION WHEN OTHERS THEN
    v_role := 'patient';
  END;

  DELETE FROM public.mood_persistent_logins WHERE expires_at <= now();

  INSERT INTO public.mood_persistent_logins (
    username, token_hash, password_hash, role, user_agent, expires_at
  ) VALUES (
    p_user, p_token_hash, p_pw, v_role, LEFT(COALESCE(p_user_agent, ''), 500), v_expires_at
  )
  ON CONFLICT (token_hash) DO UPDATE
  SET username = EXCLUDED.username,
      password_hash = EXCLUDED.password_hash,
      role = EXCLUDED.role,
      user_agent = EXCLUDED.user_agent,
      expires_at = EXCLUDED.expires_at,
      last_used_at = now();

  RETURN jsonb_build_object('status', 'ok', 'expires_at', v_expires_at, 'role', v_role);
END;
$function$;

CREATE OR REPLACE FUNCTION public.resolve_patient_id_secure(p_admin text, p_admin_pw text, p_query text)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
    v_target text;
BEGIN
    IF p_admin != 'admin' THEN RAISE EXCEPTION 'Not admin'; END IF;
    PERFORM 1 FROM users WHERE username = p_admin AND extensions.crypt(p_admin_pw, password) = password;
    IF NOT FOUND THEN RAISE EXCEPTION 'Auth failed'; END IF;

    -- 1. username 일치 확인
    SELECT username INTO v_target FROM users WHERE username = p_query LIMIT 1;
    IF v_target IS NOT NULL THEN RETURN v_target; END IF;

    -- 2. hospital_id 일치 확인
    SELECT username INTO v_target FROM users WHERE hospital_id = p_query LIMIT 1;
    IF v_target IS NOT NULL THEN RETURN v_target; END IF;

    -- 일치하는 사용자 없음
    RETURN NULL;
END;
$function$;

CREATE OR REPLACE FUNCTION public.admin_download_by_hosp_secure(p_admin text, p_admin_pw text, p_hosp_id text)
 RETURNS TABLE(record_date date, category text, value text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
    v_target_user text;
BEGIN
    IF p_admin != 'admin' THEN RAISE EXCEPTION 'Not admin'; END IF;
    PERFORM 1 FROM users WHERE username = p_admin AND extensions.crypt(p_admin_pw, password) = password;
    IF NOT FOUND THEN RAISE EXCEPTION 'Auth failed'; END IF;

    SELECT username INTO v_target_user FROM users WHERE hospital_id = p_hosp_id LIMIT 1;
    IF v_target_user IS NULL THEN RAISE EXCEPTION 'User not found'; END IF;

    RETURN QUERY SELECT r.record_date, r.category, r.value 
                 FROM records r 
                 WHERE r.username = v_target_user 
                 ORDER BY r.record_date ASC;
END;
$function$;


-- login_secure is unused by the web app; keep it closed and make it fail closed.
create or replace function public.login_secure(p_id text, p_pw text) returns jsonb
 language plpgsql security definer set search_path to 'public', 'pg_temp'
as $$
begin
  if public.mood_pw_check(p_id, p_pw) <> 'ok' then
    raise exception 'Auth failed';
  end if;
  return jsonb_build_object('username', p_id, 'role', 'patient');
end $$;
revoke execute on function public.login_secure(text, text) from public, anon, authenticated;
-- Legacy functions that are already not callable by anon/authenticated: make that explicit.
do $$
declare f regprocedure;
begin
  for f in select p.oid::regprocedure from pg_proc p join pg_namespace n on n.oid = p.pronamespace
           where n.nspname = 'public' and p.proname in ('admin_download_by_hosp_secure', 'check_my_gifts', 'daily_check_in',
             'delete_sticker_secure', 'get_inventory', 'get_records_v2', 'get_stickers_secure', 'resolve_patient_id_secure',
             'retrieve_sticker', 'save_sticker_secure', 'send_gift', 'send_gift_anonymously', 'use_sticker')
  loop
    execute format('revoke execute on function %s from public, anon, authenticated', f);
  end loop;
end $$;
drop function if exists public.zz_tx_probe_fn();
drop table if exists public.zz_tx_probe;
notify pgrst, 'reload schema';
commit;
